//! 🏭️ The actual Host factory and complete instance representation preserve the same paid Core through denied transfer and closure.
use semio_framework_plugin_host::{GuestRuntimes,GuestRuntime,GuestInstance,GuestActorOpening,CompiledHandle,PackageRef,PackageHash};
use semio_framework_actor::{OriginalGuestExecutionBudget,RetainedTurnInput};
use std::mem::size_of;
#[global_allocator]
static ALLOCATOR:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
use semio_framework_plugin_interpreter::OwnedSemioExport;
use semio_framework_plugin_interpreter_runtime::OwnedRuntime;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};
use semio_framework_value::RetainedCloneGrant;
#[path="../../../🧠️interpreter/🏃️runtime/🧪️tests/🧫️fixtures/🌱️channel/🦀️.rs"]
mod channel_fixture;
fn clock()->Option<u64>{Some(1000)}
fn grant()->RetainedCloneGrant{RetainedCloneGrant{maximum_items:10000,maximum_copy_bytes:2_000_000,maximum_capacity_bytes:2_000_000,maximum_release_bytes:2_000_000,maximum_depth:64}}
fn observed<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn core_bytes(component:&[u8])->&[u8]{assert_eq!(component[8],1);let mut pc=9;let mut length=0;let mut shift=0;loop{let byte=component[pc];pc+=1;length|=usize::from(byte&127)<<shift;shift+=7;if byte&128==0{break}}&component[pc..pc+length]}
/// 📤️ The production enum is priced before relocation, and every failed original-source validation retains that actual owner.
#[test]
fn original_host_factory_keeps_actual_core_and_paid_terminal_state(){
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../../🧠️interpreter/🏃️runtime/🏗️startup/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let bytes=channel_fixture::owned_channel_guest(semio_framework_os_kernel::CHANNEL_VERSION);let engine=wasmtime::Engine::default();let module=wasmtime::Module::new(&engine,core_bytes(&bytes)).unwrap();let mut store=wasmtime::Store::new(&engine,());let oracle=wasmtime::Instance::new(&mut store,&module,&[]).unwrap();let packed=oracle.get_typed_func::<(),i64>(&mut store,OwnedSemioExport::ChannelVersion.core_name()).unwrap().call(&mut store,()).unwrap()as u64;let memory=oracle.get_memory(&mut store,"memory").unwrap().data(&store);let offset=packed as u32 as usize;let channel:u32=serde_json::from_slice(&memory[offset..offset+(packed>>32)as usize]).unwrap();assert_eq!(channel,semio_framework_os_kernel::CHANNEL_VERSION);
 let backend=OwnedRuntime::new(clock);let runtime=GuestRuntimes::Owned(backend);let package=PackageRef{package:semio_framework_actor::PackageId("original-host-factory".into()),hash:PackageHash([7;32])};let compiled=semio_framework_async::block_on(runtime.compile(&package,&bytes)).unwrap();let actor=semio_framework_async::block_on(semio_framework_actor::ActorId::new(7,1,3,0));let stock=grant();let mut caller=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let mut epoch=1;let mut opening=caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.begin_original_actor_step(&compiled,actor,cx)}).unwrap();let mut born=0;let mut released=0;let mut vm=0;
 for _ in 0..150{if opening.as_ref().unwrap().ready(){break}epoch+=1;let(call,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:1024,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let owner=opening.as_mut().unwrap();let original_input=RetainedTurnInput::borrow_original(cx)?;let execution=owner.requires_execution().then(||OriginalGuestExecutionBudget{input:original_input,fuel:1,deadline_us:cx.deadline_us()});runtime.advance_original_actor_step(owner,&compiled,execution,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);born+=heap.0;released+=heap.1;if let Some(receipt)=call.execution{vm+=receipt.spent_fuel.unwrap()}assert!(matches!(call.result.unwrap(),semio_framework_plugin_interpreter_runtime::OwnedActorStartupStatus::Pending|semio_framework_plugin_interpreter_runtime::OwnedActorStartupStatus::Ready));}
 assert!(opening.as_ref().unwrap().ready());assert_eq!(vm,fixture["expectedInstructions"].as_u64().unwrap());let pointer=opening.as_ref().unwrap().original_memory(0).unwrap().as_ptr();let mut instance=None;for copy in [fixture["nativeFactory"]["transferCopyBytes"][0].as_u64().unwrap()as usize,fixture["nativeFactory"]["transferCopyBytes"][1].as_u64().unwrap()as usize,fixture["nativeFactory"]["transferCopyBytes"][1].as_u64().unwrap()as usize]{epoch+=1;let(taken,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:copy,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;let input=RetainedTurnInput::borrow_original(cx)?;runtime.take_original_actor_step(&mut opening,&compiled,input,cx)}).unwrap());assert_eq!(heap,(0,0));if copy==0{assert!(taken.is_none());assert!(opening.is_some());assert_eq!(caller.receipt(),Default::default());}if let Some(taken)=taken{instance=Some(taken);break}}
 let mut instance=instance.expect("paid final original Host owner");assert_eq!(instance.actor,actor);assert!(opening.is_none());let original_pointer=|instance:&mut GuestInstance|instance.original_memory(0).unwrap().as_ptr();assert_eq!(original_pointer(&mut instance),pointer);let mut foreign=OriginalJobFixtureCaller::admit(OperationId(71),Generation(3),stock,clock,100000,100000);let(result,heap)=observed(||foreign.turn(stock,|cx|{cx.bind_original_source_epoch(epoch+1)?;runtime.close_original_instance_step(&mut instance,&compiled,cx)}));assert!(result.is_err());assert_eq!(heap,(0,0));assert_eq!(original_pointer(&mut instance),pointer);foreign.retire(stock);epoch+=1;let(done,heap)=observed(||caller.turn(RetainedCloneGrant{maximum_copy_bytes:0,..stock},|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_instance_step(&mut instance,&compiled,cx)}).unwrap());assert!(!done);assert_eq!(heap,(0,0));assert_eq!(original_pointer(&mut instance),pointer);caller.cancel().cancel_now();for _ in 0..100{if instance.is_closed(){break}epoch+=1;let(_,heap)=observed(||caller.turn(stock,|cx|{cx.bind_original_source_epoch(epoch)?;runtime.close_original_instance_step(&mut instance,&compiled,cx)}).unwrap());assert_eq!((caller.receipt().retained_capacity_bytes,caller.receipt().released_bytes),heap);released+=heap.1;}assert!(instance.is_closed());assert_eq!(born,released);assert_eq!(observed(||drop(instance)).1,(0,0));caller.retire(stock);eprintln!("[DEBUG] actual Host factory productionWrapperBytes={} sameCore=true WasmtimeAndSerde=true measuredVM={vm} foreignSameBusinessSourceRefused=true cancelledTerminalClosed=true born={born} paidRelease={released}",size_of::<GuestInstance>());
}
